Uint8List? _realmL07Cache;
final Map<int, Uint8List> _realmCache = {};

Uint8List get realmL07Bytes =>
    _realmL07Cache ??= base64Decode(_kRealmL07Webp);

/// 按领地等级取 3D 渲染图（解码一次后缓存，避免每次 rebuild 重复解码）
Uint8List realmBytes(int level) {
  if (!_kRealmWebp.containsKey(level)) return realmL07Bytes;
  return _realmCache.putIfAbsent(level, () => base64Decode(_kRealmWebp[level]!));
